SELECT AVG(Total) AS AverageInvoiceTotal
FROM Invoice
GROUP BY BillingCountry;

SELECT income_group, COUNT(*) AS num_countries
FROM country_stats
GROUP BY income_group;

SELECT AVG(life_expectancy_years) AS population_weighted_avg_life_expectancy
FROM country_stats
WHERE year = 2023;

SELECT species, MIN(bill_depth_mm), MAX(bill_depth_mm) AS max_bill_depth, MIN(bill_depth_mm), MAX(bill_depth_mm) AS max_bill_depth
FROM penguins
GROUP BY species;
